const E=JourneyEngine,$=id=>document.getElementById(id),money=n=>'₹'+n.toLocaleString('en-IN');let state={items:E.clone(E.base),budget:15000,extra:0,history:[],delay:0,cancelled:false},plans=[],pending=null;
try{let saved=JSON.parse(localStorage.getItem('journeysync-v1'));if(saved&&Array.isArray(saved.items)&&typeof saved.budget==='number')state=saved;}catch{}
function save(){try{localStorage.setItem('journeysync-v1',JSON.stringify(state));}catch{}}
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function time(m){m=((m%1440)+1440)%1440;return String(Math.floor(m/60)).padStart(2,'0')+':'+String(m%60).padStart(2,'0');}
function view(name){document.querySelectorAll('.view').forEach(x=>x.hidden=x.id!==name);document.querySelectorAll('[data-view]').forEach(x=>x.classList.toggle('active',x.dataset.view===name));}
function render(){let issues=E.detect(state.items),cost=state.items.reduce((s,x)=>s+x.cost,0)+state.extra;let affected=new Set(issues.map(x=>x.id));$('count').textContent=issues.length;$('status').textContent=issues.length?'Needs attention':'On track';$('status').style.color=issues.length?'#b97923':'#16765d';$('statusnote').textContent=issues.length?affected.size+' activities need review':'All connections are feasible';$('spend').textContent=money(cost);$('budgetnote').textContent=money(state.budget-cost)+(state.budget>=cost?' remaining in budget':' over budget');$('budget').value=state.budget;$('navcount').textContent=issues.length?'· '+issues.length:'';$('teamstatus').textContent=issues.length?'Needs attention':'On track';$('teamcost').textContent=money(cost);
let day=-1;$('timeline').innerHTML=state.items.map(x=>{let d=Math.floor(x.start/1440),heading=d!==day?'<div class="day">'+(19+d)+' OCTOBER 2026 · '+(d===0?'MONDAY':'TUESDAY')+'</div>':'';day=d;let notes=issues.filter(y=>y.id===x.id);return heading+'<div class="activity '+(notes.length?'risk':'')+'"><div class="time">'+time(x.start)+'<small>'+time(x.end)+'</small></div><div class="icon">'+x.icon+'</div><div class="activitybody"><div class="top"><b>'+esc(x.title)+'</b><span class="type">'+x.type+'</span></div><p>'+esc(x.detail)+(x.cancelled?' · CANCELLED':'')+'</p>'+notes.map(n=>'<div class="risknote">⚠ '+esc(n.message)+'</div>').join('')+(x.deps.length?'<div class="buffer">↳ '+x.deps[0].buffer+' min buffer after '+state.items.find(y=>y.id===x.deps[0].id).type.toLowerCase()+'</div>':'')+'</div></div>';}).join('');
$('insighttitle').textContent=issues.length?'An upstream change has consequences':'A healthy connection chain';$('insight').textContent=issues.length?'Your disrupted flight affects linked activities. Review recovery options to protect your fixed appointments.':'Your flight has a 45-minute arrival buffer before the transfer. Every activity fits its downstream dependency.';
$('graphnodes').innerHTML=state.items.map(x=>'<div class="graphnode"><span class="icon">'+x.icon+'</span><div><b>'+esc(x.title)+'</b><br><small>'+time(x.start)+'–'+time(x.end)+(x.fixed?' · Fixed appointment':'')+'</small></div></div>'+state.items.filter(y=>y.deps.some(d=>d.id===x.id)).map(y=>'<div class="graphlink">↓ '+y.deps.find(d=>d.id===x.id).buffer+' min buffer → '+esc(y.title)+'</div>').join('')).join('');
$('alerts').innerHTML=issues.length?issues.map(x=>'<div class="alert">⚠ '+esc(x.message)+'</div>').join(''):'<div class="alert ok">✓ No scheduling conflicts. You can simulate a delay from the timeline to test recovery.</div>';
plans=E.recover(state.items,state.budget-state.extra);plans.forEach(p=>{p.total+=state.extra;p.extra+=state.extra;});$('plans').innerHTML=plans.map((p,i)=>'<article class="plan '+(p.feasible&&i===0?'recommended':'')+'"><span class="badge '+(p.feasible?'green':'')+'">'+(p.feasible?(i===0?'BEST FEASIBLE PLAN':'FEASIBLE ALTERNATIVE'):'CONSTRAINT NOT MET')+'</span><h3>'+p.title+'</h3><p>'+p.description+'</p><strong>'+money(p.total)+'</strong><p>'+money(p.extra-state.extra)+' additional cost</p><p>'+ (p.conflicts.length?p.conflicts.length+' unresolved conflicts': 'All scheduling constraints satisfied')+'</p>'+(p.total>state.budget?'<p class="risknote">Exceeds your budget by '+money(p.total-state.budget)+'</p>':'')+'<button class="'+(p.feasible?'primary':'secondary')+'" data-plan="'+p.id+'" '+(!p.feasible?'disabled':'')+'>Review & approve →</button></article>').join('');
let log=state.history.length?state.history.map(x=>'<div class="log">'+esc(x.title)+' · '+money(x.cost)+'<small>'+esc(x.when)+' · Approved locally · Simulated changes only</small></div>').join(''):'No recovery plans applied yet.';$('history').innerHTML=log;$('teamhistory').innerHTML=log;save();document.dispatchEvent(new Event('journeyupdated'));}
document.addEventListener('click',ev=>{let nav=ev.target.closest('[data-view]');if(nav)view(nav.dataset.view);let p=ev.target.closest('[data-plan]');if(p){pending=plans.find(x=>x.id===p.dataset.plan);$('approvaltext').textContent=pending.title+'. '+pending.description+' Total estimated cost: '+money(pending.total)+'. This updates the demo itinerary; no bookings or messages will be sent.';$('consent').checked=false;$('confirm').disabled=true;$('approval').showModal();}});
$('delay').value=state.delay;$('delaylabel').textContent=state.delay+' min';$('delay').oninput=()=>{$('delaylabel').textContent=$('delay').value+' min';};
function disrupt(cancelled){state.items=E.clone(E.base);state.delay=Number($('delay').value);state.cancelled=cancelled;state.extra=0;state.items[0].start+=state.delay;state.items[0].end+=state.delay;state.items[0].cancelled=cancelled;render();view('recovery');toast(cancelled?'Cancellation detected. Recovery plans calculated.':'Delay applied. Downstream connections checked.');}
$('simulate').onclick=()=>disrupt(false);$('cancel').onclick=()=>disrupt(true);$('budget').onchange=()=>{let b=Number($('budget').value);if(Number.isFinite(b)&&b>=0){state.budget=b;render();}else $('budget').value=state.budget;};$('calculate').onclick=()=>{render();toast('Recovery options recalculated.');};$('consent').onchange=()=>{$('confirm').disabled=!$('consent').checked;};$('closemodal').onclick=()=>{$('approval').close();pending=null;};$('confirm').onclick=()=>{if(!pending||!$('consent').checked)return;state.items=E.clone(pending.items);state.extra=pending.extra;state.history.unshift({title:pending.title,cost:pending.total,when:new Date().toLocaleString('en-IN',{timeZone:'Asia/Kolkata'})});$('approval').close();pending=null;render();view('journey');toast('Recovery approved. Your timeline has been updated.');};$('reset').onclick=()=>{state={items:E.clone(E.base),budget:15000,extra:0,history:[],delay:0,cancelled:false};$('delay').value=0;$('delaylabel').textContent='0 min';render();view('journey');toast('Demo reset to the original journey.');};$('export').onclick=()=>{let blob=new Blob([JSON.stringify({...state,conflicts:E.detect(state.items),dataSource:'simulated',timezone:'Asia/Kolkata'},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='journeysync-itinerary.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};let toastTimer;function toast(s){$('toast').textContent=s;$('toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').style.display='none',4500);}render();
